const {subjects,articles,revision}=window.KNOWLEDGE;
const articleIds=new Set(articles.map(a=>a.id));
async function loadContent(resource){
  if(window.ZHIMA_OFFLINE){
    if(resource==='search.json')return window.ZHIMA_OFFLINE.search;
    return window.ZHIMA_OFFLINE.articles[resource.slice(9,-5)];
  }
  const response=await fetch(resource+'?v='+encodeURIComponent(revision||''));
  if(!response.ok)throw new Error('加载失败：'+resource);
  return response.json();
}
const $=s=>document.querySelector(s);
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',book:'<path d="M12 5C8 2 4 3 2 4v15c4-2 7-1 10 1 3-2 6-3 10-1V4c-3-1-7-2-10 1Zm0 0v15"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M8 5h8a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h8"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4V3Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',moon:'<path d="M20.5 14A9 9 0 0 1 10 3.5 9 9 0 1 0 20.5 14Z"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',check:'<path d="m5 12 4 4L20 5"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1.5 1.5m11 11L19 19M5 19l1.5-1.5m11-11L19 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>'};
function icon(n){return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[n]||paths.book}</svg>`}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(e=>e.innerHTML=icon(e.dataset.icon))}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={saved:[],done:[],recent:[],theme:'light',days:[]};
try{const saved=JSON.parse(localStorage.getItem('zhima-learning-v1')||'null');if(saved&&typeof saved==='object')for(const key of Object.keys(state))if(typeof saved[key]===typeof state[key])state[key]=saved[key];}catch{}
for(const key of ['saved','done','recent'])state[key]=Array.isArray(state[key])?[...new Set(state[key].filter(id=>articleIds.has(id)))]:[];
state.days=Array.isArray(state.days)?state.days:[];
let storageAvailable=true;let renderToken=0;let searchCorpus=null;let searchQueryToken=0;let toastTimer;
function persist(){try{localStorage.setItem('zhima-learning-v1',JSON.stringify(state));}catch{storageAvailable=false;toast('浏览器存储不可用，本次进度仅在当前页面保留');}syncCounts()}
function syncCounts(){document.querySelectorAll('.saved-count').forEach(x=>x.textContent=state.saved.length)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2200)}
function subject(s){return subjects.find(x=>x.id===s)}
function subjectIcon(s){return `<span class="subject-icon ${s}">${s==='flutter'?'<svg viewBox="0 0 24 24" fill="currentColor"><path d="m13 2-11 11 4 4L21 2Zm0 11-5 5 4 4h9l-8-9Z"/></svg>':s==='android'?'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round"><path d="m7 6-2-3m12 3 2-3M4 13a8 8 0 0 1 16 0v5H4Z"/><circle cx="8" cy="11" r=".7" fill="currentColor"/><circle cx="16" cy="11" r=".7" fill="currentColor"/></svg>':subject(s).icon}</span>`}
function bookmark(a){return `<button class="bookmark-button ${state.saved.includes(a.id)?'saved':''}" data-save="${a.id}" aria-label="${state.saved.includes(a.id)?'取消收藏':'收藏'}：${esc(a.title)}" aria-pressed="${state.saved.includes(a.id)}">${icon('bookmark')}</button>`}
function row(a,detailed=false){return `<div class="article-row" data-read="${a.id}">${subjectIcon(a.subject)}<div class="article-info"><h3><a href="#article/${a.id}">${state.done.includes(a.id)?'✓ ':''}${esc(a.title)}</a></h3>${detailed?`<p class="summary">${esc(a.summary)}</p>`:''}<p>${a.tags.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}<span>${esc(subject(a.subject).name)}</span></p></div><span class="row-time">${a.minutes} min</span>${bookmark(a)}</div>`}
function pathCard(s){const n=state.done.filter(id=>articles.find(a=>a.id===id)?.subject===s.id).length;return `<a class="path-card" href="#library/${s.id}"><div class="path-card-top">${subjectIcon(s.id)}<span class="card-arrow">↗</span></div><h3>${s.name}</h3><p>${s.description}</p><div class="path-card-bottom"><span>${s.count} 篇知识笔记</span><span>${n?`已学 ${n} 篇`:'探索领域'} ↗</span></div></a>`}
function featured(){const selected=(window.KNOWLEDGE.featured||[]).map(p=>articles.find(a=>a.source.startsWith(p))).filter(Boolean);return [...new Map([...selected,...articles].map(a=>[a.id,a])).values()].slice(0,3)}
function home(){const date=new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long'}).format(new Date());const algorithmArticles=articles.filter(a=>a.subject==='algorithm');const picks=algorithmArticles.length?algorithmArticles:articles;const pickIndex=Math.floor(Date.now()/86400000)%picks.length;const challenge=picks[pickIndex];return `<div class="welcome-line"><p>欢迎回来，今天也保持好奇心 <span style="color:#c7b870">✧</span></p><span class="date">${icon('calendar')} ${date}</span></div>
<section class="hero"><div><div class="eyebrow">YOUR PERSONAL DEVELOPER KNOWLEDGE BASE</div><h1>连接知识，<br>构建你的<em>技术宇宙。</em></h1><p>从一个知识点，到一整套体系。<br>在这里沉淀、探索，让每一次学习都有迹可循。</p><div class="hero-buttons"><a class="button primary" href="#paths">开启学习之旅 ${icon('arrow')}</a><a class="text-link" href="#library">探索全部知识 ↗</a></div></div><div class="hero-art" aria-label="持续学习的代码插画"><div class="orbit"></div><span class="floating-star">✦</span><div class="code-window"><div class="code-bar"><i></i><i></i><i></i><span>growth.ts</span></div><div class="hero-code"><span class="comment">// 一点积累，无限可能</span>
<span class="purple">const</span> developer = {
  curiosity: <b>Infinity</b>,
  knowledge: [<b>'learn'</b>, <b>'build'</b>],
  <span class="purple">grow</span>() {
    <span class="purple">return</span> <b>this</b>.learn().repeat();
  }
};</div></div><span class="floating-braces">{ }</span></div></section>
<div class="stats"><div class="stat"><b>${articles.length}</b><span>篇知识笔记</span></div><div class="stat-divider"></div><div class="stat"><b>${String(subjects.length).padStart(2,'0')}</b><span>大技术领域</span></div><div class="stat-divider"></div><div class="stat"><b>${String(state.done.length).padStart(2,'0')}</b><span>篇已掌握</span></div><div class="stat"><span><i class="green-dot"></i>每一次积累，都算数</span></div></div>
<section><div class="section-title"><h2>探索知识领域 <small>EXPLORE TOPICS</small></h2><a href="#paths">查看学习路径 ↗</a></div><div class="path-grid">${subjects.map(pathCard).join('')}</div></section>
<div class="home-bottom"><section><div class="section-title"><h2>${state.recent.length?'继续探索':'值得一读'} <small>FOR YOU</small></h2><a href="#library">查看全部 ↗</a></div><div class="tabs" id="home-tabs"><button class="tab active" data-home-tab="all">精选推荐</button>${subjects.map(s=>`<button class="tab" data-home-tab="${s.id}">${esc(s.name)}</button>`).join('')}</div><div class="panel article-list" id="home-articles">${(state.recent.length?[...state.recent.map(id=>articles.find(a=>a.id===id)).filter(Boolean),...featured().filter(a=>!state.recent.includes(a.id))].slice(0,3):featured()).map(a=>row(a)).join('')}</div><div class="note-line">${icon('book')} 知识源于积累，理解来自实践。</div></section><aside class="home-aside"><div class="section-title"><h2>每日一题 <small>DAILY PICK</small></h2><span style="font-size:10px;color:#99a28f">${String(pickIndex+1).padStart(2,'0')} / ${picks.length}</span></div><div class="panel challenge"><div class="challenge-heading"><div class="eyebrow">A LITTLE CHALLENGE, EVERY DAY</div><span>✧</span></div><h3>${esc(challenge.title)}</h3>${challenge.tags.slice(0,2).map(t=>`<span class="tag">${esc(t)}</span>`).join(' ')}<p>${esc(challenge.summary)}</p><a class="button" href="#article/${challenge.id}">${algorithmArticles.length?'开始解题':'开始阅读'} ${icon('arrow')}</a></div><a class="mini-progress" href="#progress"><span>${algorithmArticles.length?'我的算法进度':'我的学习进度'}</span><b>${state.done.filter(id=>picks.some(a=>a.id===id)).length} <span style="color:#a8b39b;font-size:9px">/ ${picks.length}</span> ↗</b></a></aside></div>`}
let currentFilter='all',currentPage=1,currentSort='default';
function library(filter='all',saved=false){currentFilter=filter;const s=subject(filter);return `<div class="page-heading"><div class="eyebrow">${saved?'YOUR PERSONAL COLLECTION':'A GROWING KNOWLEDGE UNIVERSE'}</div><h1>${saved?'我的收藏':s?s.name:'全部知识'}</h1><p>${saved?'把值得反复阅读的知识，留在触手可及的地方。':s?s.description:'从基础概念到深入原理，找到你此刻想理解的知识。'}</p></div><div class="library-toolbar"><div class="tabs">${[{id:'all',name:'全部'},...subjects].map(s=>`<button class="tab ${s.id===filter?'active':''}" data-filter="${s.id}" data-mode="${saved?'saved':'library'}">${s.name}</button>`).join('')}</div><select id="sort" aria-label="排序方式"><option value="default">按学习顺序</option><option value="short">阅读时长最短</option><option value="unread">未掌握优先</option></select></div><div id="library-items"></div>`}
function updateLibrary(saved=false){let list=articles.filter(a=>(currentFilter==='all'||a.subject===currentFilter)&&(!saved||state.saved.includes(a.id)));if(currentSort==='short')list.sort((a,b)=>a.minutes-b.minutes);if(currentSort==='unread')list.sort((a,b)=>Number(state.done.includes(a.id))-Number(state.done.includes(b.id)));const pages=Math.max(1,Math.ceil(list.length/15));currentPage=Math.min(currentPage,pages);$('#library-items').innerHTML=`<p class="library-count">${list.length} 篇笔记${currentFilter==='all'?` · 跨越 ${subjects.length} 大技术领域`:''}</p>${list.length?`<div class="panel library-list">${list.slice((currentPage-1)*15,currentPage*15).map(a=>row(a,true)).join('')}</div><div class="pagination"><button class="button" data-page="${currentPage-1}" ${currentPage===1?'disabled':''}>← 上一页</button><span>${currentPage} / ${pages}</span><button class="button" data-page="${currentPage+1}" ${currentPage===pages?'disabled':''}>下一页 →</button></div>`:`<div class="panel empty-state">${icon('bookmark')}<h2>把好知识收藏在这里</h2><p>点击文章右侧的书签，即可添加到你的收藏。</p><a class="button primary" href="#library">去发现知识 ${icon('arrow')}</a></div>`}`;$('#sort').value=currentSort}
const stages=Object.fromEntries(subjects.map(s=>[s.id,s.stages?.length?s.stages:['基础知识','进阶原理','实践应用']]));
function pathPage(){return `<div class="page-heading"><div class="eyebrow">ONE STEP AT A TIME</div><h1>给知识一条生长的路径。</h1><p>选一个方向，从基础到进阶，把零散的知识连成线。</p></div>${subjects.map(s=>{const done=state.done.filter(id=>articles.find(a=>a.id===id)?.subject===s.id).length;const next=articles.find(a=>a.subject===s.id&&!state.done.includes(a.id));return `<section class="panel path-detail"><div class="path-detail-header">${subjectIcon(s.id)}<div><h2>${s.name}</h2><p>${s.count} 篇笔记 · 基础 → 进阶 → 实践</p></div><a class="button primary" href="${next?'#article/'+next.id:'#library/'+s.id}">${done?'继续学习':'开始学习'} ${icon('arrow')}</a></div><div class="path-stages">${stages[s.id].map((t,i)=>`<span class="stage"><span>0${i+1}</span>${t}</span>`).join('<span style="color:#bdc8b5;align-self:center">→</span>')}</div><div class="progress-bar"><span style="width:${Math.round(done/s.count*100)}%"></span></div><div class="progress-caption"><span>已掌握 ${done} / ${s.count} 篇</span><a href="#library/${s.id}">浏览全部笔记 ↗</a></div></section>`}).join('')}`}
function progress(){return `<div class="page-heading"><div class="eyebrow">SMALL STEPS, REAL PROGRESS</div><h1>看见你的每一点积累。</h1><p>学过的知识、珍藏的笔记，都在这里留下足迹。</p></div><div class="progress-summary"><div class="panel"><strong>${state.done.length}</strong><span>篇已掌握知识</span></div><div class="panel"><strong>${state.saved.length}</strong><span>篇收藏笔记</span></div><div class="panel"><strong>${state.days.length}</strong><span>个学习日</span></div></div><div class="section-title"><h2>各领域掌握进度</h2></div>${subjects.map(s=>{const n=state.done.filter(id=>articles.find(a=>a.id===id)?.subject===s.id).length;return `<div class="panel path-detail"><div class="path-detail-header">${subjectIcon(s.id)}<div><h2>${s.name}</h2><p>${n} / ${s.count} 篇</p></div><a class="text-link" href="#library/${s.id}">继续探索 ↗</a></div><div class="progress-bar"><span style="width:${n/s.count*100}%"></span></div></div>`}).join('')}<div class="section-title" style="margin-top:28px"><h2>最近阅读</h2></div><div class="panel article-list">${state.recent.length?state.recent.slice(0,6).map(id=>articles.find(a=>a.id===id)).filter(Boolean).map(a=>row(a)).join(''):'<div class="empty-state"><p>还没有阅读记录，从感兴趣的一篇开始吧。</p><a href="#library" class="button primary">浏览知识库</a></div>'}</div><p class="storage-note">收藏、掌握状态与学习记录保存在当前浏览器，不会跨设备同步。阅读文章后，点击「标记掌握」记录学习成果。</p>`}
async function reader(id,token){const a=articles.find(a=>a.id===id);if(!a){$('#main').innerHTML='<div class="empty-state"><h2>没有找到这篇笔记</h2><a href="#library" class="button primary">返回知识库</a></div>';return}$('#crumb').textContent=subject(a.subject).name;$('#main').innerHTML='<div class="empty-state"><p>正在打开知识笔记…</p></div>';try{const data=await loadContent(`articles/${id}.json`);if(token!==renderToken)return;state.recent=[id,...state.recent.filter(i=>i!==id)].slice(0,30);persist();const next=articles.find(x=>x.subject===a.subject&&x.order>a.order);$('#main').innerHTML=`<div class="reader-head"><a href="#library/${a.subject}">← 返回${subject(a.subject).name}</a><div class="reader-actions"><button class="button" data-save="${id}">${icon('bookmark')} ${state.saved.includes(id)?'已收藏':'收藏文章'}</button><button class="button primary" id="mark-done" data-id="${id}">${icon('check')} ${state.done.includes(id)?'已掌握':'标记掌握'}</button></div></div><div class="reader-layout"><div class="panel reader-paper"><div class="reader-meta"><span class="tag">${subject(a.subject).name}</span><span>${esc(a.category)}</span><span>${a.minutes} 分钟阅读</span></div><article class="markdown" id="article-body">${data.html}</article><div class="reader-source">原文：${esc(a.source)}<p class="reader-note">本文整理自你的本地知识资料，保留原始讲解与代码；技术内容以原文为准。</p></div><div class="reader-next"><button class="button primary" id="bottom-done" data-id="${id}">${icon('check')} ${state.done.includes(id)?'已掌握，继续巩固':'读完了，标记掌握'}</button>${next?`<a class="text-link" href="#article/${next.id}">下一篇 ${icon('arrow')}</a>`:'<a class="text-link" href="#paths">探索其他学习路径 ↗</a>'}</div></div><aside class="reader-toc"><strong>本篇目录</strong><div id="toc-items"></div></aside></div>`;
const headings=[...document.querySelectorAll('#article-body h2')];$('#toc-items').innerHTML=headings.map((h,i)=>{h.id='section-'+i;return `<a href="#section-${i}" data-section="section-${i}">${esc(h.textContent)}</a>`}).join('');document.querySelectorAll('.markdown pre').forEach(p=>{const b=document.createElement('button');b.className='copy-code';b.textContent='复制代码';b.onclick=async()=>{try{await navigator.clipboard.writeText(p.querySelector('code')?.textContent||p.textContent.replace('复制代码',''));b.textContent='已复制';setTimeout(()=>b.textContent='复制代码',1500)}catch{toast('复制失败，请选中代码后复制')}};p.append(b)});
document.querySelectorAll('.markdown a').forEach(link=>{const href=link.getAttribute('href')||'';if(/^https?:/.test(href)){link.target='_blank';link.rel='noopener noreferrer'}else if(href.startsWith('#')){link.onclick=e=>{e.preventDefault();const h=document.getElementById(decodeURIComponent(href.slice(1)));if(h)h.scrollIntoView({behavior:'smooth'})}}else if(href.includes('.md')){try{const resolved=new URL(href,'https://local/'+a.source).pathname.slice(1);const target=articles.find(x=>x.source===decodeURIComponent(resolved));if(target)link.href='#article/'+target.id;else{link.removeAttribute('href');link.title='关联文件未收录'}}catch{link.removeAttribute('href')}}});}catch{if(token!==renderToken)return;$('#main').innerHTML='<div class="empty-state"><h2>文章加载失败</h2><p>请检查连接后重试。</p><button class="button primary" id="retry-article">重新加载</button></div>';$('#retry-article').onclick=render}}
function render(){const token=++renderToken;const [page='home',arg]=(location.hash.slice(1)||'home').split('/');document.title=`${({home:'知识概览',library:'全部知识',paths:'学习路径',saved:'我的收藏',progress:'学习记录',article:'知识阅读'})[page]||'知码'} · 知码`;$('#crumb').textContent=({home:'知识概览',library:'全部知识',paths:'学习路径',saved:'我的收藏',progress:'学习记录',article:'知识阅读'})[page]||'知识概览';document.querySelectorAll('[data-nav]').forEach(e=>e.classList.toggle('active',e.dataset.nav===page));$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false');if(page==='article'){reader(arg,token);window.scrollTo(0,0);return}currentPage=1;currentSort='default';if(page==='library'||page==='saved'){$('#main').innerHTML=library(arg||'all',page==='saved');updateLibrary(page==='saved')}else $('#main').innerHTML=page==='paths'?pathPage():page==='progress'?progress():home();window.scrollTo(0,0)}
document.addEventListener('click',e=>{const save=e.target.closest('[data-save]');if(save){e.preventDefault();e.stopPropagation();const id=save.dataset.save;const had=state.saved.includes(id);state.saved=had?state.saved.filter(i=>i!==id):[...state.saved,id];persist();toast(had?'已取消收藏':'已加入我的收藏');if(location.hash.startsWith('#article')){save.innerHTML=icon('bookmark')+(had?' 收藏文章':' 已收藏')}else if(location.hash.startsWith('#saved'))updateLibrary(true);else{save.classList.toggle('saved',!had);save.setAttribute('aria-pressed',String(!had));save.setAttribute('aria-label',(had?'收藏':'取消收藏')+'：'+articles.find(a=>a.id===id).title)}return}const complete=e.target.closest('#mark-done,#bottom-done');if(complete){const id=complete.dataset.id;if(state.done.includes(id)){state.done=state.done.filter(i=>i!==id);toast('已调整为待巩固')}else{state.done.push(id);const now=new Date();const today=[now.getFullYear(),String(now.getMonth()+1).padStart(2,'0'),String(now.getDate()).padStart(2,'0')].join('-');if(!state.days.includes(today))state.days.push(today);toast('又掌握了一点新知识，继续加油！')}persist();$('#mark-done').innerHTML=icon('check')+(state.done.includes(id)?' 已掌握':' 标记掌握');$('#bottom-done').innerHTML=icon('check')+(state.done.includes(id)?' 已掌握，继续巩固':' 读完了，标记掌握');return}const filter=e.target.closest('[data-filter]');if(filter){const hash='#'+filter.dataset.mode+(filter.dataset.filter==='all'?'':'/'+filter.dataset.filter);if(location.hash===hash){currentPage=1;updateLibrary(filter.dataset.mode==='saved')}else location.hash=hash;return}const pg=e.target.closest('[data-page]');if(pg&&!pg.disabled){currentPage=Number(pg.dataset.page);updateLibrary(location.hash.startsWith('#saved'));window.scrollTo({top:120,behavior:'smooth'});return}const tab=e.target.closest('[data-home-tab]');if(tab){document.querySelectorAll('[data-home-tab]').forEach(t=>t.classList.toggle('active',t===tab));const list=tab.dataset.homeTab==='all'?featured():articles.filter(a=>a.subject===tab.dataset.homeTab).slice(0,3);$('#home-articles').innerHTML=list.map(a=>row(a)).join('');return}const section=e.target.closest('[data-section]');if(section){e.preventDefault();document.getElementById(section.dataset.section)?.scrollIntoView({behavior:'smooth'});return}const r=e.target.closest('[data-read]');if(r&&!e.target.closest('a,button'))location.hash='#article/'+r.dataset.read;});
document.addEventListener('change',e=>{if(e.target.id==='sort'){currentSort=e.target.value;currentPage=1;updateLibrary(location.hash.startsWith('#saved'))}});
$('#subject-nav').innerHTML=subjects.map(s=>`<a href="#library/${s.id}"><span class="subject-dot ${s.id}"></span>${s.name}<span class="nav-count">${s.count}</span></a>`).join('');
function applyTheme(){document.body.classList.toggle('dark',state.theme==='dark');$('#theme-toggle').innerHTML=icon(state.theme==='dark'?'sun':'moon');$('#theme-toggle').setAttribute('aria-label',state.theme==='dark'?'切换浅色模式':'切换深色模式')}
$('#theme-toggle').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';applyTheme();persist()};
$('#mobile-menu').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#mobile-menu').setAttribute('aria-expanded',String(open))};
document.addEventListener('click',e=>{if(innerWidth<=650&&!e.target.closest('#sidebar,#mobile-menu')){$('#sidebar').classList.remove('open');$('#mobile-menu').setAttribute('aria-expanded','false')}});
function openSearch(){$('#search-dialog').showModal();$('#search-input').focus();runSearch($('#search-input').value)}$('#open-search').onclick=openSearch;$('#close-search').onclick=()=>$('#search-dialog').close();$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog')){const b=$('#search-dialog').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)$('#search-dialog').close()}};
async function runSearch(q){const token=++searchQueryToken;const terms=q.trim().toLowerCase().split(/\s+/).filter(Boolean);if(!terms.length){$('#search-meta').textContent=`搜索你的 ${articles.length} 篇知识笔记 · 也可以从这些主题开始`;$('#search-results').innerHTML=featured().map(searchResult).join('');return}$('#search-meta').textContent='正在搜索…';if(!searchCorpus){try{searchCorpus=await loadContent('search.json')}catch{if(token!==searchQueryToken)return;$('#search-meta').textContent='正文索引加载失败，已使用标题与标签搜索'}}if(token!==searchQueryToken)return;const list=articles.map(a=>({a,score:terms.reduce((sum,t)=>sum+(a.title.toLowerCase().includes(t)?10:0)+(a.tags.join(' ').toLowerCase().includes(t)?4:0),0)})).filter(({a})=>terms.every(t=>(a.title+' '+a.tags.join(' ')+' '+(searchCorpus?.[a.id]||a.summary)).toLowerCase().includes(t))).sort((a,b)=>b.score-a.score);$('#search-meta').textContent=`找到 ${list.length} 篇相关笔记${list.length>30?' · 显示前 30 篇':''}`;$('#search-results').innerHTML=list.length?list.slice(0,30).map(({a})=>searchResult(a)).join(''):'<div class="empty-state"><h2>还没有找到相关笔记</h2><p>试试「闭包」「三棵树」「哈希」或更短的关键词。</p></div>'}
function searchResult(a){return `<button class="search-result" data-search-open="${a.id}"><b>${esc(a.title)}</b><small>${subject(a.subject).name} · ${esc(a.tags.join(' / '))} · ${a.minutes} 分钟阅读</small></button>`}
let searchTimer;$('#search-input').oninput=e=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>runSearch(e.target.value),150)};$('#search-results').onclick=e=>{const b=e.target.closest('[data-search-open]');if(b){$('#search-dialog').close();location.hash='#article/'+b.dataset.searchOpen}};$('#search-input').onkeydown=e=>{if(e.key==='Enter')$('#search-results [data-search-open]')?.click()};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();if($('#search-dialog').open)$('#search-dialog').close();else openSearch()}if(e.key==='Escape')$('#sidebar').classList.remove('open')});
window.addEventListener('hashchange',render);hydrate();applyTheme();syncCounts();render();
